import sys

def is_palindrome(s):
    return s == s[::-1]

def find_longest_palindrome(a, b):
    max_palindrome = ""
    for i in range(len(a)):
        for j in range(i + 1, len(a) + 1):
            sa = a[i:j]
            for k in range(len(b)):
                for l in range(k + 1, len(b) + 1):
                    sb = b[k:l]
                    candidate = sa + sb
                    if is_palindrome(candidate) and len(candidate) > len(max_palindrome):
                        max_palindrome = candidate
                    elif is_palindrome(candidate) and len(candidate) == len(max_palindrome) and candidate < max_palindrome:
                        max_palindrome = candidate
    return max_palindrome if max_palindrome else "-1"

input = sys.stdin.read().strip().split('\n')
q = int(input[0])
results = []
for i in range(q):
    a = input[2 * i + 1]
    b = input[2 * i + 2]
    results.append(find_longest_palindrome(a, b))

for result in results:
    print(result)
